parameters.jsCode:
let callId = null, lastNode = 'unknown', errMsg = 'unknown error', workflowName = 'SOPBot Main';
try {
  const err = $input.first().json;
  const execution = err.execution || {};
  lastNode = execution.lastNodeExecuted || err.node?.name || 'unknown';
  let rawMsg = execution.error?.message || err.errorMessage || err.error?.message || execution.error?.description || 'no message available';
  // Sanitize: strip HTML-special chars, collapse whitespace, hard cap length so the alert email itself can never be rejected as oversized/malformed
  errMsg = String(rawMsg).replace(/<[^>]*>/g, '').replace(/[<>&"']/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);
  workflowName = (err.workflow && err.workflow.name) || workflowName;
  try {
    const runData = execution.data?.resultData?.runData;
    if (runData && runData['3. Parse Vapi Payload']) {
      callId = runData['3. Parse Vapi Payload'][0].data.main[0][0].json.call_id;
    }
  } catch (innerErr) {
    // call_id extraction is best-effort; absence is handled downstream via 'Has Call ID?' branch
  }
} catch (outerErr) {
  errMsg = 'Error handler itself failed to parse trigger payload: ' + String(outerErr.message).slice(0, 200);
}

return [{
  json: { call_id: callId, failed_node: lastNode, error_message: errMsg, workflow_name: workflowName }
}];

